def _coords(elem):
    if elem is None:
        return None
    try:
        return [int(x) for x in list(elem)]
    except TypeError:
        pass
    for attr in ("getArray", "get_array", "toArray", "to_array"):
        fn = getattr(elem, attr, None)
        if callable(fn):
            return [int(x) for x in fn()]
    return str(elem)

def _ias(lst):
    if lst is None:
        return None
    return [_coords(x) for x in list(lst)]

