def _seq_close(alg, gens):
    old = getattr(Closer, 'doParallel', False)
    try:
        Closer.doParallel = False
        return _sorted_ias(_quiet(Closer(alg, gens)).sgClose())
    finally:
        Closer.doParallel = old

